<?php
/* TEMPORARY (owner, 12 Nov 2026): full backup, then create the art_places table (art_places.sql, add-only)
   and save the Art Map places as DRAFTS: the 21 earlier drafts (from site_settings 'art_places') and the
   124 new places from the owner's 148-place file (24 duplicates skipped). A row whose src_ref already
   exists is never changed. Nothing else changes. Locked by a secret key, runs once. Removed straight after. */
if (!hash_equals('ddeb1169ac58d9aa75eb2592c6d2f146180cdcaf424d7c61af91809ad3dbefc6', hash('sha256', (string) ($_GET['k'] ?? '')))) { http_response_code(404); exit; }
require_once __DIR__ . '/config.php';
header('Content-Type: text/plain; charset=utf-8'); header('Cache-Control: no-store'); header('X-Robots-Tag: noindex');
@set_time_limit(300);
$db = getDB();
$dbName = (string) $db->query('SELECT DATABASE()')->fetchColumn();
$show = function () use ($db) {
    $t = $db->query("SHOW TABLES LIKE 'art_places'")->fetchColumn();
    if (!$t) { echo "art_places: no table yet\n"; return; }
    foreach ($db->query('SELECT kind, status, COUNT(*) n, SUM(photo_path <> \'\') ph, SUM(confidence = \'low\') low FROM art_places GROUP BY kind, status') as $r) echo implode(' | ', array_map('strval', $r)), "\n";
};
if (($_GET['a'] ?? '') !== 'run') { echo "ready, database $dbName\n"; $show(); exit; }
if (is_file(__DIR__ . '/.logs/zz-places-done')) { echo "already run\n"; $show(); exit; }

/* 1. full backup */
$dir = __DIR__ . '/.backups';
if (!is_dir($dir)) { @mkdir($dir, 0700, true); }
if (!is_file($dir . '/.htaccess')) { @file_put_contents($dir . '/.htaccess', "Require all denied\n"); }
$file = $dir . '/db-' . preg_replace('/[^a-z0-9_]/i', '', $dbName) . '-' . gmdate('Ymd-His') . '.sql.gz';
$gz = gzopen($file, 'wb6');
if (!$gz) { echo "backup FAILED: cannot write\n"; exit; }
gzwrite($gz, "-- Oweili full backup " . gmdate('c') . "\nSET NAMES utf8mb4;\nSET FOREIGN_KEY_CHECKS=0;\n");
$tables = $db->query('SHOW FULL TABLES WHERE Table_type = "BASE TABLE"')->fetchAll(PDO::FETCH_COLUMN);
$rows = 0;
foreach ($tables as $t) {
    $t = str_replace('`', '', (string) $t);
    $c = $db->query("SHOW CREATE TABLE `$t`")->fetch(PDO::FETCH_NUM);
    gzwrite($gz, "\nDROP TABLE IF EXISTS `$t`;\n" . $c[1] . ";\n");
    $st = $db->query("SELECT * FROM `$t`");
    while ($r = $st->fetch(PDO::FETCH_NUM)) {
        $vals = array_map(fn($v) => $v === null ? 'NULL' : $db->quote((string) $v), $r);
        gzwrite($gz, "INSERT INTO `$t` VALUES (" . implode(',', $vals) . ");\n");
        $rows++;
    }
}
gzwrite($gz, "\nSET FOREIGN_KEY_CHECKS=1;\n");
gzclose($gz);
$size = (int) filesize($file);
if ($size < 500) { echo "backup FAILED (too small)\n"; exit; }
echo "backup ok: .backups/" . basename($file) . " (" . count($tables) . " tables, $rows rows, $size bytes)\n";

/* 2. the table (add-only) */
$db->exec(base64_decode(''));
/* 3. the drafts */
$rows = json_decode(base64_decode(''), true);
if (!is_array($rows) || count($rows) !== 145) { echo "data FAILED\n"; exit; }
$cols = ['src_ref','kind','status','name_en','name_ar','city_en','city_ar','region','desc_en','desc_ar','address','phone','website','instagram','maps_url','lat','lng','photo_path','photo_credit','photo_page','photo_license','sources','confidence'];
$st = $db->prepare('INSERT IGNORE INTO art_places (' . implode(',', $cols) . ') VALUES (' . implode(',', array_map(fn($c) => ':' . $c, $cols)) . ')');
$n = 0;
foreach ($rows as $r) {
    if (($r['status'] ?? '') !== 'draft') { echo "not a draft, stopped\n"; exit; }
    $a = []; foreach ($cols as $c) $a[':' . $c] = $r[$c] ?? null;
    $st->execute($a); $n += $st->rowCount();
}
@file_put_contents(__DIR__ . '/.logs/zz-places-done', gmdate('c'));
echo "saved $n new rows\n"; $show();
